<script setup lang="ts">
import { computed } from 'vue'
import type { Evidence } from '../api'
type Statement = {text:string;rule_id:string;evidence_ids:string[];calculation?:Record<string,unknown>;origin?:string;assessment?:string}
type Hypothesis = {explanation:string;status:string;evidence_ids?:string[];missing_evidence?:string[]}
type QueryChoice = {query_id:string;tool:string;pair_count?:number|null;cost_units?:number|null;partition?:Record<string,string[]>;unknown_hypothesis_ids?:string[];unpredicted_hypothesis_ids?:string[];eligible?:boolean;exclusion_reason?:string|null;proposal_query_id?:string}
type EvidenceSelection = {hypotheses?:{hypothesis_id:string;explanation:string}[];selected_query?:QueryChoice|null;candidates?:QueryChoice[];selection?:{action?:string;status?:string;reason?:string;reason_code?:string;evidence_request?:{description?:string;reason?:string}};execution?:{performed?:boolean;status?:string;record_evidence_ids?:string[];requires_new_snapshot?:boolean;retrieved?:boolean}}
type ProviderUsage = {prompt_tokens?:number|null;completion_tokens?:number|null;total_tokens?:number|null;prompt_cache_hit_tokens?:number|null;prompt_cache_miss_tokens?:number|null}
type ModelRequest = {request_index?:number|null;provider_model?:string|null;request_usage?:ProviderUsage|null}
const props=defineProps<{result:{status:string;claims:Statement[];hypotheses:Hypothesis[];proposed_claims?:Statement[];missing_evidence?:string[];model?:string|null;prompt_version?:string;usage?:Record<string,number>;evidence_selections?:EvidenceSelection[];model_requests?:ModelRequest[]};evidence:Evidence[]}>()
const emit=defineEmits<{inspect:[evidence:Evidence]}>()
const labels:Record<string,string>={invoice_id:'发票号',invoice_amount:'发票金额',recognized_amount:'已确认金额',excess:'超额确认',voucher_ids:'关联凭证',debit:'借方合计',credit:'贷方合计',difference:'差额',received:'已收货金额',ordered:'订单金额',order_amount:'订单金额',receipt_amount:'收货金额',gap:'差额',account:'会计科目',calculated:'计算余额',reported:'报送余额'}
const names:Record<string,string>={supported:'证据支持',normal:'正常差异',insufficient:'证据不足',unsupported:'超出支持范围',failed:'运行失败',budget_exhausted:'预算耗尽',refuted:'已排除',unresolved:'待查证'}
const byId=computed(()=>new Map(props.evidence.map(row=>[row.id,row])))
const evidenceFor=(ids:string[]=[])=>ids.map(id=>byId.value.get(id)).filter((row):row is Evidence=>!!row)
const value=(v:unknown)=>Array.isArray(v)?v.join(' / '):v===null?'未知':String(v)
const assessments:Record<string,string>={finding:'观察到差异',normal:'检查正常',insufficient:'资料不足',unsupported:'超出范围'}
const tools:Record<string,string>={query_journal_lines:'查询账务分录',get_business_chain:'查询业务资料链',match_transactions:'核对交易匹配',retrieve_policy:'查阅适用规则',verify_claims:'核验引用与指标'}
const exclusions:Record<string,string>={already_executed:'已执行过相同查询',not_available:'当前不可执行',no_distinguishable_pairs:'没有可区分的解释对'}
const count=(v:unknown)=>typeof v==='number'&&Number.isSafeInteger(v)&&v>=0?v.toLocaleString('zh-CN'):'未报告'
const missingIds=(ids:string[]=[])=>ids.filter(id=>!byId.value.has(id))
const needsEvidence=(selection:EvidenceSelection)=>selection.selection?.action==='request_evidence'||selection.execution?.status==='evidence_requested'
const executionLabel=(selection:EvidenceSelection)=>needsEvidence(selection)?'补证请求':selection.execution?.performed===true?'已执行当前快照查询':selection.execution?.performed===false?'查询尚未执行':'执行状态未报告'
</script>
<template>
 <div class="investigation-results">
  <div v-if="result.model" class="run-metadata"><span>模型 <code>{{ result.model }}</code></span><span>API 请求 {{ result.usage?.calls??'未知' }} 次</span><span>已报告 Token {{ result.usage?.tokens?.toLocaleString()??'未知' }}</span><span>工具调用 {{ result.usage?.tools??'未知' }} 次</span><span v-if="result.usage?.reserved_tokens">未知计费预留 {{ result.usage.reserved_tokens.toLocaleString() }} Token</span><small>Token 用量不代表金额；{{ result.prompt_version }}</small></div>
  <details v-if="result.model||result.model_requests?.length" class="provider-usage">
   <summary>模型逐次用量<span v-if="result.model_requests?.length"> · 已报告 {{ result.model_requests.length }} 次返回</span></summary>
   <p class="caption">下列计数来自服务端返回。缺失字段显示“未报告”；失败或未返回请求的用量可能未知，Token 不代表实际费用。</p>
   <div v-if="result.model_requests?.length" class="usage-table-wrap"><table class="usage-table"><caption class="visually-hidden">服务端逐次返回的模型用量</caption><thead><tr><th>请求</th><th>服务端模型</th><th>输入 Token</th><th>输出 Token</th><th>缓存命中</th><th>缓存未命中</th><th>总 Token</th></tr></thead><tbody><tr v-for="(request,i) in result.model_requests" :key="i"><th scope="row">{{ count(request.request_index) }}</th><td>{{ request.provider_model||'未报告' }}</td><td>{{ count(request.request_usage?.prompt_tokens) }}</td><td>{{ count(request.request_usage?.completion_tokens) }}</td><td>{{ count(request.request_usage?.prompt_cache_hit_tokens) }}</td><td>{{ count(request.request_usage?.prompt_cache_miss_tokens) }}</td><td>{{ count(request.request_usage?.total_tokens) }}</td></tr></tbody></table></div>
   <p v-else class="caption">尚未报告逐次用量。</p>
  </details>
  <section v-if="result.evidence_selections?.length" class="evidence-selection-section">
   <div class="section-title"><h3>主动取证选择</h3><span>{{ result.evidence_selections.length }} 次选择记录</span></div>
   <p class="caption">预期分区来自待验证的解释，既不是校准概率，也不是会计事实；查询执行结果单独展示。</p>
   <article v-for="(selection,i) in result.evidence_selections" :key="i" class="selection-card">
    <div class="selection-heading"><span class="selection-index">{{ String(i+1).padStart(2,'0') }}</span><strong>{{ selection.selected_query?tools[selection.selected_query.tool]||selection.selected_query.tool:'需补充证据' }}</strong><span :class="['badge',selection.execution?.performed===true?'success':'warning']">{{ executionLabel(selection) }}</span></div>
    <div v-if="selection.hypotheses?.length" class="planned-hypotheses"><h4>候选解释 · 待验证</h4><p v-for="hypothesis in selection.hypotheses" :key="hypothesis.hypothesis_id"><code>{{ hypothesis.hypothesis_id }}</code><span>{{ hypothesis.explanation }}</span></p></div>
    <div v-if="selection.selected_query" class="selection-score"><div><span>预期可区分解释对数</span><strong>{{ count(selection.selected_query.pair_count) }}</strong></div><span class="score-divider" aria-hidden="true">÷</span><div><span>服务端成本单位</span><strong>{{ count(selection.selected_query.cost_units) }}</strong></div><small>用于查询排序，成本单位不是货币。</small></div>
    <p v-if="selection.selection?.reason" class="selection-reason">{{ selection.selection.reason }}</p>
    <details v-if="selection.candidates?.length" class="candidate-queries"><summary>候选查询与预期分区（{{ selection.candidates.length }}）</summary><div v-for="candidate in selection.candidates" :key="candidate.query_id" class="query-candidate"><div class="query-candidate-heading"><code>{{ candidate.proposal_query_id||candidate.query_id }}</code><span>{{ tools[candidate.tool]||candidate.tool }}</span><span>{{ candidate.eligible===true?'可参与选择':exclusions[candidate.exclusion_reason||'']||'不可参与选择' }}</span></div><p class="caption">可区分 {{ count(candidate.pair_count) }} 对解释 / 成本 {{ count(candidate.cost_units) }} 单位</p><dl v-if="Object.keys(candidate.partition||{}).length" class="partition"><template v-for="(ids,label) in candidate.partition" :key="label"><dt>{{ label }}</dt><dd>{{ ids.join('、') }}</dd></template></dl><p v-if="candidate.unknown_hypothesis_ids?.length" class="caption">结果未知：{{ candidate.unknown_hypothesis_ids.join('、') }}（不计可区分对）</p><p v-if="candidate.unpredicted_hypothesis_ids?.length" class="caption">尚未预测：{{ candidate.unpredicted_hypothesis_ids.join('、') }}（不计可区分对）</p></div></details>
    <div v-if="needsEvidence(selection)" class="selection-missing"><strong>补充资料尚未取得</strong><p>{{ selection.selection?.evidence_request?.description||'需要补充能区分候选解释的资料。' }}</p><p>补充资料后需创建新快照，再继续调查。</p></div>
    <div v-else-if="selection.execution?.performed===true" class="statement-evidence execution-evidence"><span>查询返回证据</span><button v-for="row in evidenceFor(selection.execution.record_evidence_ids)" :key="row.id" type="button" class="evidence-chip" @click="emit('inspect',row)">{{ row.source_id }}</button><span v-for="id in missingIds(selection.execution.record_evidence_ids)" :key="id" class="unloaded-evidence"><code>{{ id }}</code> · 未载入</span><span v-if="!selection.execution.record_evidence_ids?.length">本次查询没有账务记录引用。</span></div>
   </article>
  </section>
  <div class="section-title"><h3>已核验结果</h3><span>{{ names[result.status]||result.status }}</span></div>
  <article v-for="(claim,i) in result.claims||[]" :key="i" class="statement-card">
   <div class="statement-source"><span class="badge success">程序核验</span><code>{{ claim.rule_id }}</code></div>
   <p>{{ claim.text }}</p>
   <dl v-if="Object.keys(claim.calculation||{}).length" class="statement-metrics"><template v-for="(v,key) in claim.calculation" :key="key"><dt>{{ labels[key]||key }}</dt><dd>{{ value(v) }}</dd></template></dl>
   <div class="statement-evidence"><span>来源证据</span><button v-for="row in evidenceFor(claim.evidence_ids)" :key="row.id" class="evidence-chip" @click="emit('inspect',row)">{{ row.source_id }}</button></div>
  </article>
  <section v-if="result.proposed_claims?.length" class="proposal-section"><h3>模型建议 · 待复核</h3><p class="caption">引用校验通过仅代表来源存在，建议仍需判断业务适用性。</p><article v-for="(claim,i) in result.proposed_claims" :key="i" class="statement-card proposal"><span v-if="claim.assessment" class="badge warning">{{ assessments[claim.assessment]||claim.assessment }}</span><p>{{ claim.text }}</p><div class="statement-evidence"><button v-for="row in evidenceFor(claim.evidence_ids)" :key="row.id" class="evidence-chip" @click="emit('inspect',row)">{{ row.source_id }}</button></div></article></section>
  <details v-if="result.hypotheses?.length"><summary>候选解释与反证（{{ result.hypotheses.length }}）</summary><article v-for="(hypothesis,i) in result.hypotheses" :key="i" class="hypothesis-card"><span class="badge warning">{{ names[hypothesis.status]||hypothesis.status }}</span><p>{{ hypothesis.explanation }}</p><ul v-if="hypothesis.missing_evidence?.length"><li v-for="need in hypothesis.missing_evidence" :key="need">{{ need }}</li></ul></article></details>
  <details v-if="result.missing_evidence?.length"><summary>尚需补充的资料</summary><ul><li v-for="need in result.missing_evidence" :key="need">{{ need }}</li></ul></details>
  <details><summary>完整运行记录（JSON）</summary><pre>{{ JSON.stringify(result,null,2) }}</pre></details>
 </div>
</template>
<style scoped>
.run-metadata{display:flex;flex-wrap:wrap;gap:10px 18px;padding:14px 16px;margin:16px 0;background:#f4f5ed;border:1px solid #e4ebdc;border-radius:6px;font-size:11px;color:#596d49}.run-metadata small{flex-basis:100%;color:#86967a}.run-metadata code{font-size:11px}
.provider-usage{border:1px solid #e4ebdc;border-radius:6px;padding:12px 16px;background:#fffefa}.usage-table-wrap{overflow:auto}.usage-table{border-collapse:collapse;width:100%;font-size:10px;text-align:right;white-space:nowrap}.usage-table th,.usage-table td{padding:9px 12px;border-bottom:1px solid #e4ebdc}.usage-table thead th{color:#758767;font-weight:500}.usage-table th:first-child,.usage-table td:nth-child(2){text-align:left}.usage-table td{font-variant-numeric:tabular-nums}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.evidence-selection-section{margin:24px 0}.selection-card{padding:18px;margin:12px 0;border:1px solid #dce6d2;background:#fffefa;border-radius:6px}.selection-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:12px}.selection-index{font:11px Consolas,monospace;color:#86967a}.selection-heading .badge{margin-left:auto}.planned-hypotheses{border-left:2px solid #c8ba93;padding-left:12px;margin:16px 0}.planned-hypotheses h4{font-size:11px;color:#758767;font-weight:500;margin:0 0 10px}.planned-hypotheses p{display:flex;gap:10px;margin:8px 0;font-size:12px;line-height:1.8}.planned-hypotheses code{font-size:10px;color:#86967a;flex-shrink:0;max-width:35%;overflow-wrap:anywhere}.selection-score{display:flex;align-items:center;gap:18px;padding:13px 15px;background:#f5f8ef;border-radius:4px;flex-wrap:wrap}.selection-score>div{display:flex;flex-direction:column;gap:6px}.selection-score>div>span{font-size:10px;color:#758767}.selection-score strong{font:22px Consolas,monospace;color:#466343}.score-divider{color:#c8ba93}.selection-score small{font-size:10px;color:#87947d;margin-left:auto}.selection-reason{font-size:12px;line-height:1.8;color:#596d49}.query-candidate{margin:12px 0;padding:12px 0;border-top:1px solid #e4ebdc}.query-candidate-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:10px;color:#758767}.query-candidate-heading code{overflow-wrap:anywhere;max-width:100%}.query-candidate-heading>span:last-child{margin-left:auto}.partition{display:grid;grid-template-columns:minmax(80px,1fr) minmax(0,2fr);font-size:11px;margin:8px 0;gap:6px}.partition dt{color:#87947d;overflow-wrap:anywhere}.partition dd{margin:0;color:#596d49;overflow-wrap:anywhere}.selection-missing{padding:12px 14px;background:#fcf8ec;border-left:2px solid #c8ba93;font-size:11px;line-height:1.8}.selection-missing strong{font-weight:500;color:#776942}.selection-missing p{margin:6px 0}.execution-evidence{margin-top:14px}.unloaded-evidence{color:#87947d;font-size:10px;overflow-wrap:anywhere}.evidence-chip:focus-visible{outline:2px solid #466343;outline-offset:2px}@media(max-width:520px){.selection-card{padding:14px}.selection-heading .badge{margin-left:0}.selection-score{gap:14px}.selection-score small{flex-basis:100%;margin-left:0}.planned-hypotheses p{gap:7px}}
.statement-card{background:#f5f8ef;border:1px solid #e4ebdc;border-radius:6px;padding:18px;margin:12px 0;font-size:12px}.statement-card p{line-height:1.9;margin:12px 0}.statement-source{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.statement-source code{font-size:10px;color:#86967a}.statement-metrics{display:grid;grid-template-columns:minmax(90px,1fr) minmax(0,2fr);gap:0;margin:12px 0}.statement-metrics dt,.statement-metrics dd{padding:8px 0;border-bottom:1px solid #e4ebdc;margin:0}.statement-metrics dt{color:#87947d}.statement-metrics dd{font-family:Consolas,monospace;text-align:right;overflow-wrap:anywhere}.statement-evidence{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:10px}.statement-evidence>span{color:#87947d;margin-right:5px}.evidence-chip{border:1px solid #d8e2cd;background:#fffefa;color:#466343;border-radius:4px;padding:4px 7px;font-family:Consolas,monospace;max-width:100%;overflow-wrap:anywhere}.evidence-chip:hover{background:#e8f0df}.hypothesis-card{border-left:2px solid #c8ba93;margin:14px 0;padding:3px 15px}.hypothesis-card p{margin:8px 0;font-size:12px}.proposal{background:#fcf8ec}.proposal-section{margin-top:24px}ul{padding-left:20px;color:#7a896e;font-size:11px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:380px;overflow:auto;font-size:10px}details{margin:14px 0}summary{font-size:11px;color:#758767;cursor:pointer}
</style>
